/** Önerinin kendisi (değiştirilmişse karşılaştırmak için) */
public class ResetSegmentDataRecommendation(
    /** Always present. */
    public val name: String,
    /**
     * Kartın ÜZERİNDE çalışan koşullar; hepsi birlikte (VE). En az bir koşul gerekir.
     *
     * Always present.
     */
    public val rule: ResetSegmentDataRecommendationRule,
) : RewloyObject() {
    internal companion object {
        fun read(v: JsonValue, path: String): ResetSegmentDataRecommendation {
            val o = ObjectReader(v, path)
            return ResetSegmentDataRecommendation(
                name = o.str("name"),
                rule = o.req("rule") { x, y -> ResetSegmentDataRecommendationRule.read(x, y) },
            ).also { it.adopt(o.rest()) }
        }
    }
}

/** Kartın ÜZERİNDE çalışan koşullar; hepsi birlikte (VE). En az bir koşul gerekir. */
public class ResetSegmentDataRecommendationRule(
    /** Pencerede en az N ziyaret */
    public val minVisits: Int?,
    /** Pencerede en çok N ziyaret (0: hiç gelmemiş) */
    public val maxVisits: Int?,
    /** Ziyaret ve şube kurallarının penceresi (varsayılan 90 gün) */
    public val windowDays: Int?,
    /** N gündür gelmeyen (hiç gelmediyse kartı aldığından beri) */
    public val quietDays: Int?,
    /** Kartını son N günde alan */
    public val joinedWithinDays: Int?,
    /** Ödülü hazır bekleyen */
    public val rewardReady: Boolean?,
    /** Damga/puan kartında yolun dörtte üçünü geçmiş, ödül henüz yok */
    public val nearReward: Boolean?,
    /** Doğum ayı 1–12; 0 = gönderim/sayım anındaki ay */
    public val birthdayMonth: Int?,
    /** `programId`. */
    public val programId: String?,
    /** Ana şubesi bunlardan biri ya da pencerede burada ziyareti olan */
    public val locationIds: List<String>?,
) : RewloyObject() {
    internal companion object {
        fun read(v: JsonValue, path: String): ResetSegmentDataRecommendationRule {
            val o = ObjectReader(v, path)
            return ResetSegmentDataRecommendationRule(
                minVisits = o.intOrNull("minVisits"),
                maxVisits = o.intOrNull("maxVisits"),
                windowDays = o.intOrNull("windowDays"),
                quietDays = o.intOrNull("quietDays"),
                joinedWithinDays = o.intOrNull("joinedWithinDays"),
                rewardReady = o.boolOrNull("rewardReady"),
                nearReward = o.boolOrNull("nearReward"),
                birthdayMonth = o.intOrNull("birthdayMonth"),
                programId = o.strOrNull("programId"),
                locationIds = o.opt("locationIds") { x, y -> Wire.list(x, y) { v1, p1 -> Wire.string(v1, p1) } },
            ).also { it.adopt(o.rest()) }
        }
    }
}

